import 'package:flutter/material.dart'; import '../../models/challenge_model.dart'; import '../../models/project_model.dart';
class AppStore extends ChangeNotifier { final challenges=<Challenge>[Challenge(id:'CH-2025-00124',title:'Water Contamination in Village',category:'Water Management',location:'Ranchi, Jharkhand',description:'The drinking water in our village is polluted and causing health issues for people.',priority:'High')]; final projects=<Project>[Project(name:'Water Purification System',university:'BIT Mesra',category:'Water Management')]; final chats=<String>['Dr. Priya: Welcome to the project workspace!','You: Looking forward to collaborating.']; Challenge addChallenge(String t,String d,String cat,String l){final c=Challenge(id:'CH-2025-${(120+challenges.length).toString().padLeft(5,'0')}',title:t,description:d,category:cat,location:l,status:'Submitted');challenges.insert(0,c);notifyListeners();return c;} void assign(Challenge c,String u){c.status='Assigned to $u';notifyListeners();} void accept(Challenge c){c.status='In Progress';notifyListeners();} Project createProject(String n,String m){final p=Project(name:n,university:'BIT Mesra',category:'Water Management',mentor:m,progress:20);projects.insert(0,p);notifyListeners();return p;} void advance(Project p){if(p.activeMilestone<p.milestones.length-1){p.activeMilestone++;p.progress=((p.activeMilestone+1)/p.milestones.length*100).round();notifyListeners();}} void send(String m){if(m.trim().isNotEmpty){chats.add('You: ${m.trim()}');notifyListeners();}} }
class StoreScope extends InheritedNotifier<AppStore>{const StoreScope({super.key,required AppStore store,required super.child}):super(notifier:store);static AppStore of(BuildContext c)=>c.dependOnInheritedWidgetOfExactType<StoreScope>()!.notifier!;}
